// Keep existing route controllers; present one game-style application shell.
const beforeGameShellRender=render;render=function(){beforeGameShellRender();const route=location.hash.slice(1)||'home',home=route==='home';document.body.classList.add('game-shell');document.body.classList.toggle('farm-screen',home);if(home&&account&&selectedFarmCity()==='krasnodar'){$('#app').innerHTML=farmMap();requestAnimationFrame(()=>{fitFarmCamera();farmCameraObserver?.disconnect();const viewport=document.querySelector('.farm-camera-viewport');if(viewport){farmCameraObserver=new ResizeObserver(fitFarmCamera);farmCameraObserver.observe(viewport)}})}document.querySelectorAll('#app > .context-tabs').forEach(el=>el.remove());statusBanner.textContent='Демо · оплата тестовыми средствами';statusBanner.title='Реальные деньги не списываются';userButton.setAttribute('title',account?'Мой профиль':'Войти / регистрация');};
render();
